function apaList(start,end){return '<div class="apa-list">'+APA_REFERENCES.slice(start,end).map(r=>'<p class="apa-entry">'+(r.lead?esc(r.lead)+' ':'')+'<em>'+esc(r.italic)+'</em>'+(r.tail?(r.tail.startsWith('(')?'':' ')+esc(r.tail):'')+(r.url?' <a href="'+esc(r.url)+'" target="_blank" rel="noopener">'+esc(r.url)+'</a>':'')+'</p>').join('')+'</div>'}

window.SLIDES = [
 {...block('Consumo del aire comprimido','Sistemas neumáticos',c=>`<div class="cover"><div><p class="eyebrow">Manufactura automatizada</p><h1>Sistemas<br>neumáticos</h1><p class="lead">Válvulas, cilindros y actuadores.<br>El aire se convierte en movimiento.</p><div class="meta">${c.nombre?`<strong>${esc(c.nombre)}</strong><br>`:''}${esc(c.curso)}<br>Profesor: ${esc(c.profesor)}${c.fecha?`<br>${esc(c.fecha)}`:''}</div></div><div class="svgwrap">${machine('cover')}</div></div>`,{dark:true,sources:'Esquemas didácticos propios. Sin escala.'}),seconds:15,layout:'cover',notes:'En esta presentación veremos cómo una máquina utiliza el aire comprimido para realizar movimientos. Nos concentraremos en las válvulas que controlan el aire, los actuadores que lo convierten en trabajo y la integración de estos componentes en procesos industriales.'},
 {...block('01 · Ubicación del tema','Del aire atmosférico al consumo',()=>`<div class="scope-flow">${[['01','Generación'],['02','Almacenamiento<br>y tratamiento'],['03','Distribución'],['04','Consumo<br>en la máquina']].map(([n,t],i)=>`${i?'<span class="arrow" aria-hidden="true">›</span>':''}<div class="station ${i<3?'dim':''}"><span>${n}</span><h3>${t}</h3></div>`).join('')}</div><div class="scope-zoom"><p class="big">Nuestro alcance empieza<br><span class="accent">dentro de la máquina.</span></p><button class="zoom-button" data-next>Entrar a la máquina ↗</button></div><p class="annotation">Etapas conceptuales: el orden físico de almacenamiento y tratamiento puede variar.</p>`,{subtitle:'Recordatorio del recorrido general del aire.'}),seconds:25,notes:'Como ya vimos en clase, el aire se comprime, se almacena y se acondiciona antes de distribuirse a los equipos. Aquí solo necesitamos recordar ese recorrido. Nuestra presentación comienza en el último bloque: la máquina consumidora, donde el aire disponible se controla y se utiliza para realizar una operación.'},
 {...block('02 · Dentro de la máquina','Controlar el aire. Realizar trabajo.',()=>`<div class="split wide"><div><div class="svgwrap">${machine('inside',{signal:true})}</div><div class="legend"><span><i></i>Alimentación</span><span><i class="out"></i>Descarga</span><span><i class="sig"></i>Mando</span></div></div><div><ol class="steps"><li>Válvula<small>Establece las conexiones.</small></li><li>Cilindro<small>Produce el movimiento.</small></li><li>Proceso<small>Recibe el trabajo mecánico.</small></li></ol><p class="takeaway">La orden y la energía siguen recorridos distintos.</p></div></div>`,{sources:'Esquema conceptual propio · Escenario didáctico de expulsión de piezas.'}),seconds:35,notes:'Dentro de esta máquina encontramos una válvula conectada al suministro y un cilindro conectado a la válvula mediante mangueras. La válvula establece por dónde circula el aire. El cilindro transforma la acción de ese aire en movimiento y empuja la pieza. Además, existe una señal que ordena el cambio de la válvula. Conviene distinguir esa orden del aire que aporta la energía.'},
 {...block('03 · Funcionamiento general','Un ciclo de avance y retorno',()=>`<div class="split wide"><div><div class="svgwrap">${machine('cycle')}</div><div class="scene-controls"><button data-cycle="0" class="selected">1 · Reposo</button><button data-cycle="1">2 · Avance</button><button data-cycle="2">3 · Retorno</button><button data-auto-cycle>Reproducir ciclo</button></div><div class="legend"><span><i></i>Cámara alimentada</span><span><i class="out"></i>Cámara en descarga</span></div></div><div><ol class="steps" data-cycle-steps><li class="current">Reposo<small>Cilindro retraído.</small></li><li>Avance<small>Se alimenta A y se descarga B.</small></li><li>Retorno<small>Se alimenta B y se descarga A.</small></li></ol></div></div>`,{sources:refs(['valves','cylinders'])+' · Esquema didáctico, sin escala.'}),seconds:45,notes:'Primero, el cilindro está retraído y la máquina espera la orden. Al activar la válvula, el aire entra a una cámara del cilindro y el aire de la cámara opuesta sale por el escape. La diferencia de fuerzas mueve el émbolo y el vástago empuja la pieza. Al retirar la orden, la válvula de este ejemplo vuelve a su posición inicial e invierte las conexiones para producir el retorno. Ahora vamos a estudiar los componentes que hacen posible esta secuencia.'},
 {...block('04 · Fundamentos','Fuerza y velocidad',()=>`<div class="compare"><div><p class="mini-label">Presión y área</p><p class="formula">F<sub>teórica</sub> = p A</p><p>Determinan la fuerza disponible.</p><div class="svgwrap">${miniCylinder('force')}</div></div><div><p class="mini-label">Caudal y área</p><p class="formula">v ≈ Q / A</p><p>Relacionan flujo y velocidad.</p><div style="margin-top:50px"><div class="name-row">El comportamiento real también depende de:</div><p class="big" style="margin-top:20px">Carga, fricción<br>y restricciones.</p></div></div></div><p class="annotation">Modelos simplificados. p: presión manométrica con escape atmosférico; Q: caudal volumétrico en la cámara, no caudal normalizado.</p>`,{sources:'Material de clase: Neumática Industrial · '+refs(['sizing'])}),seconds:45,notes:'Para entender el sistema necesitamos distinguir presión y caudal. La presión, junto con el área del émbolo, determina la fuerza teórica disponible. El caudal está relacionado con la velocidad a la que se llena o vacía la cámara y, por tanto, con la velocidad del movimiento. Son relaciones útiles, aunque el comportamiento real también depende de la carga, la fricción y las restricciones del circuito. Aumentar la presión no equivale simplemente a ajustar la velocidad. En la relación de caudal usamos el volumen en las condiciones de la cámara, no litros normalizados.'},
 {...block('05 · Válvulas','Cuatro funciones de control',()=>`<table class="flat-table"><thead><tr><th>Tipo de válvula</th><th>Qué controla</th><th>En la máquina</th></tr></thead><tbody><tr><td>Direccional</td><td>Conexiones del circuito</td><td>Avance y retorno</td></tr><tr><td>Control de caudal</td><td>Paso del aire</td><td>Ajuste de velocidad</td></tr><tr><td>Regulación de presión</td><td>Presión de trabajo</td><td>Fuerza disponible</td></tr><tr><td>Antirretorno</td><td>Sentido de circulación</td><td>Paso en un solo sentido</td></tr></tbody></table><p class="takeaway">Nos concentraremos en dirección y caudal.</p>`,{sources:'Material de clase: Neumática Industrial · '+refs(['valves','flow'])}),seconds:30,notes:'Las válvulas cumplen funciones distintas. Las direccionales establecen las conexiones de alimentación y escape. Las de caudal permiten ajustar la velocidad del actuador. Los reguladores ajustan la presión de trabajo y las antirretorno restringen el sentido de circulación. Nos concentraremos principalmente en las direccionales y en el control de caudal, porque explican cómo se gobierna el movimiento.'},
 {...block('06 · Válvulas direccionales','Vías y posiciones: 3/2 y 5/2',()=>`<div class="compare"><div><h3>3 vías / 2 posiciones</h3><div class="svgwrap">${valveSymbol('v32',3)}</div><p class="small">Uso típico: cilindro de simple efecto.</p><p class="small" data-valve-desc="3">Reposo NC: 2 descarga a 3; 1 bloqueada.</p></div><div><h3>5 vías / 2 posiciones</h3><div class="svgwrap">${valveSymbol('v52',5)}</div><p class="small">Uso típico: cilindro de doble efecto.</p><p class="small" data-valve-desc="5">Posición 1: 1 alimenta 2; 4 descarga a 5.</p></div></div><div class="scene-controls"><button data-valve-position="0" class="selected">Posición 1 / reposo</button><button data-valve-position="1">Posición 2 / accionada</button></div>`,{sources:refs(['valves'])}),seconds:60,notes:'La denominación indica cuántas vías y posiciones tiene la válvula. Una 3/2 tiene tres vías y dos posiciones. En una configuración normalmente cerrada, al accionarla comunica la alimentación con el actuador; al volver al reposo, comunica el actuador con el escape. La 5/2 tiene cinco vías y dos posiciones. Puede alimentar una cámara mientras descarga la otra. Cuando conmuta, intercambia esas conexiones. Esta alternancia permite gobernar avance y retorno. Aquí mostramos cada cuadro por separado para seguir sus conexiones: en un símbolo completo, los dos cuadros se dibujan juntos.'},
 {...block('07 · Accionamiento','Accionamiento de la válvula',()=>`<div class="action-types"><div>Manual<p>Pulsador o palanca.</p></div><div>Mecánico</div><div>Neumático<p>Señal de presión.</p></div><div>Eléctrico<p>Bobina solenoide.</p></div></div><div class="compare bistable-box"><div><h3>Monoestable</h3><p>Vuelve al reposo al retirar la orden.</p><div class="svgwrap">${stateDemo('mono')}</div><p class="small" data-mono-label>Sin orden: posición inicial.</p></div><div><h3>Biestable</h3><p>Conserva la posición hasta la orden contraria.*</p><div class="svgwrap">${stateDemo('bi')}</div><p class="small" data-bi-label>Sin orden: última posición.</p></div></div><div class="scene-controls"><button data-order="on">Dar orden</button><button data-order="off">Retirar orden</button><button data-order="reset">Orden contraria / reiniciar</button></div><p class="annotation">*En condiciones normales de operación. La posición de reposo no garantiza por sí sola una condición segura.</p>`,{sources:'Material de clase: Electroneumática · '+refs(['valves'])}),seconds:40,notes:'Una válvula puede accionarse con un pulsador, por contacto mecánico, mediante una señal neumática o mediante una bobina eléctrica. También importa qué ocurre al retirar la orden. Una monoestable retorna a su posición de reposo, frecuentemente por un resorte. Una biestable conserva la última posición hasta recibir la orden contraria. Esta diferencia afecta la secuencia de la máquina. La posición de reposo debe evaluarse dentro del diseño del sistema; por sí sola no garantiza una condición segura.'},
 {...block('08 · Actuadores','Del aire al movimiento',()=>`<div class="three"><div><div class="svgwrap">${miniCylinder('linear')}</div><h3>Cilindro</h3><p>Desplazamiento lineal.</p></div><div class="svgwrap">${rotary('rotary1')}<h3>Actuador de giro</h3><p>Movimiento angular.</p></div><div class="svgwrap">${gripper('gripper1')}<h3>Pinza</h3><p>Agarre y liberación.</p></div></div><p class="takeaway">Los cilindros son un tipo de actuador neumático.</p>`,{sources:refs(['cylinders','rotary'])+' · Esquemas propios.'}),seconds:25,notes:'Hasta ahora vimos cómo controlar el aire. Los actuadores aprovechan esa energía para realizar trabajo. Los cilindros producen desplazamiento lineal, los actuadores de giro cambian la orientación de un mecanismo y las pinzas permiten agarrar piezas. Por tanto, los cilindros forman parte de la familia de actuadores neumáticos.'},
 {...block('09 · Cilindros','Simple efecto y doble efecto',()=>`<div class="compare"><div><h3>Simple efecto</h3><div class="svgwrap">${miniCylinder('single',true)}</div><p>Aire para un sentido del movimiento.</p><p>Retorno por resorte o fuerza externa.</p></div><div><h3>Doble efecto</h3><div class="svgwrap">${miniCylinder('double')}</div><p>Aire para avance y retorno.</p><p>Dos cámaras alimentadas alternadamente.</p></div></div><p class="takeaway">Con vástago simple y a igual presión, la fuerza teórica de retorno es menor.</p>`,{sources:refs(['cylinders','sizing'])}),seconds:50,notes:'En un cilindro de simple efecto, el aire produce fuerza en un sentido. El retorno depende de un resorte o de una fuerza externa. En uno de doble efecto, el aire actúa alternadamente sobre ambos lados del émbolo, permitiendo realizar trabajo durante el avance y el retorno. En un cilindro convencional de vástago simple, las áreas efectivas son diferentes. A igual presión, la fuerza teórica de retorno es menor porque el vástago ocupa parte del área sobre la que actúa el aire.'},
 {...block('10 · Selección','¿Cuánta fuerza ocupo?',()=>`<div class="calc-grid"><div><p class="big">Fuerza · Carrera · Velocidad<br><span class="muted">Montaje y amortiguación</span></p><div class="calc-controls"><label for="pressure">Presión: <b id="pValue">6</b> bar<input type="range" id="pressure" min="2" max="8" step="0.5" value="6"></label><label for="diameter">Diámetro: <b id="dValue">20</b> mm<input type="range" id="diameter" min="10" max="50" step="2" value="20"></label></div><div class="scene-controls"><button data-reset-calc>Volver al ejemplo</button></div></div><div><p class="mini-label">Fuerza teórica de avance</p><p class="result"><span id="forceValue">188</span> <small>N</small></p><div class="rule"></div><p class="copy">F = p · πD² / 4</p><p class="small" id="calcDetail">0,6 N/mm² × 314 mm² ≈ 188 N</p><p class="annotation">Escape atmosférico, sin fricción. No incluye contrapresión, cargas dinámicas ni margen de selección.</p></div></div><p class="takeaway">La fuerza teórica es el punto de partida, no una capacidad útil garantizada.</p>`,{sources:refs(['sizing'])+' · Cálculo propio con datos supuestos; no es un dimensionamiento final.'}),seconds:55,notes:'Seleccionar un cilindro requiere conocer cuánto debe mover, qué distancia debe recorrer y a qué velocidad. Como ejemplo, con seis bar y un émbolo de veinte milímetros, obtenemos una fuerza teórica de avance de aproximadamente ciento ochenta y ocho newtons. Este cálculo supone escape a presión atmosférica y desprecia la fricción. La fuerza útil será menor si hay fricción o contrapresión. También debemos comprobar la carga, el margen de operación, el montaje y la capacidad de amortiguar el movimiento al final de la carrera. Los controles muestran cómo cambian presión, área y fuerza; no sustituyen la selección con catálogo.'},
 {...block('11 · Otros actuadores','Orientar y agarrar piezas',()=>`<div class="compare"><div><div class="svgwrap">${rotary('rotary2')}</div><h3>Actuador de giro</h3><p>Orientar una pieza</p></div><div><div class="svgwrap">${gripper('gripper2')}</div><h3>Pinza neumática</h3><p>Manipular una pieza</p></div></div><p class="takeaway">El movimiento requerido orienta la selección del actuador.</p>`,{sources:refs(['rotary'])+' · Movimientos ilustrativos, no dimensionados.'}),seconds:30,notes:'Cuando la operación requiere cambiar la orientación de una pieza, puede utilizarse un actuador de giro. Cuando requiere tomarla y soltarla, una pinza neumática transforma la acción del aire en apertura y cierre de sus dedos. La elección empieza por el movimiento requerido y después considera aspectos como torque, fuerza de agarre, dimensiones y carga.'},
 {...block('12 · Control del movimiento','Ajustar la velocidad',()=>`<div class="split wide"><div><div class="svgwrap">${machine('speed',{regulator:true})}</div><div class="scene-controls"><button data-speed="0.45">Lento</button><button data-speed="1" class="selected">Normal</button><button data-speed="1.8">Rápido</button><button data-auto-cycle>Reproducir ciclo</button></div></div><div class="copy"><h3>Regulador unidireccional</h3><p>Restringe el caudal en un sentido.</p><p>Permite paso libre en el contrario.</p><p class="takeaway">Disposición habitual: regular el escape de la cámara que se descarga.</p></div></div><p class="annotation">*Ubicación conceptual. El regulador combina estrangulador y antirretorno. La animación compara velocidades, sin modelar la dinámica real.</p>`,{sources:refs(['flow'])}),seconds:40,notes:'Para ajustar la velocidad se utilizan reguladores de caudal. El regulador unidireccional combina una restricción ajustable con un antirretorno: en un sentido limita el flujo y en el otro permite el paso libre. Una disposición habitual en cilindros de doble efecto consiste en regular el aire que sale de la cámara que se descarga. Podemos regular avance y retorno por separado. La válvula direccional decide el recorrido; estos reguladores ajustan cómo se desarrolla el movimiento.'},
 {...block('13 · Electroneumática','Electroneumática',()=>`<div class="split wide"><div><div class="svgwrap">${machine('electric',{signal:true})}</div><div class="scene-controls"><button data-cycle="0" class="selected">Reposo</button><button data-cycle="1">Energizar bobina</button><button data-cycle="2">Retirar orden</button></div></div><div><p class="mini-label">Señal de control</p><ol class="steps"><li>Sensor o pulsador</li><li>Control<small>Relés o PLC, según la aplicación.</small></li><li>Bobina y válvula</li></ol></div></div>`,{sources:'Material de clase: Electroneumática · Esquema conceptual propio.'}),seconds:40,notes:'En la electroneumática, una señal eléctrica acciona la bobina de una válvula. El mando puede ser sencillo o formar parte de un control con relés o un PLC. La válvula conmuta y cambia el recorrido del aire que mueve el cilindro. Los sensores permiten confirmar estados, como que el cilindro llegó al final de su recorrido. Esto ayuda a coordinar la siguiente acción. La electricidad interviene en el mando, mientras que el aire comprimido aporta la energía para el movimiento de este actuador.'},
 {...block('14 · Aplicaciones industriales','Movimientos cotidianos en producción',()=>`<div class="three"><div><div class="svgwrap">${application('reject')}</div><h3>Inspección</h3><p>Expulsar una pieza rechazada de una línea.</p></div><div><div class="svgwrap">${application('clamp')}</div><h3>Ensamble</h3><p>Sujetar una pieza durante una operación.</p></div><div><div class="svgwrap">${gripper('industry')}</div><h3>Manipulación</h3><p>Tomar y liberar componentes con una pinza.</p></div></div>`,{sources:refs(['cylinders','rotary'])+' · Ejemplos genéricos ilustrados; no representan empresas específicas.'}),seconds:25,notes:'Estos sistemas aparecen en operaciones muy concretas. Un cilindro puede expulsar un producto rechazado después de una inspección. También puede sujetar una pieza durante un ensamble. Una pinza neumática puede tomar y liberar componentes dentro de una estación de manipulación. Son ejemplos de cómo distintos movimientos neumáticos participan en la producción.'},
 {...block('15 · Implementación industrial','¿Cuándo conviene la neumática?',()=>`<div class="compare"><div><p class="mini-label">Ventajas potenciales</p><h3>Movimientos rápidos y repetitivos</h3><ul><li>Soluciones mecánicas sencillas.</li><li>Inversión competitiva en tareas simples.</li><li>Integración en estaciones de producción.</li></ul></div><div><p class="mini-label">Limitaciones y requisitos</p><h3>Evaluar el sistema completo</h3><ul><li>Suministro de aire y costo energético.</li><li>Fugas, ruido de escape y mantenimiento.</li><li>Precisión intermedia limitada en circuitos convencionales.</li></ul></div></div>`,{sources:refs(['comparison'])}),seconds:50,notes:'Desde el punto de vista industrial, la neumática puede facilitar la automatización de movimientos repetitivos con soluciones relativamente sencillas. La inversión inicial puede ser atractiva, especialmente en tareas simples y cuando la planta ya dispone de aire comprimido. Pero debemos evaluar el sistema completo. El aire tiene un costo energético, las fugas generan pérdidas y se necesita mantenimiento. Además, los circuitos convencionales presentan limitaciones para posicionar con precisión entre los extremos de la carrera. La decisión depende de la fuerza, la precisión, el ritmo de producción y el costo total durante la vida útil.'},
 {...block('16 · Tecnologías relacionadas','Neumática conectada y configurable',()=>`<div class="split equal"><div><div class="terminal" aria-label="Esquema de terminal de válvulas"><div class="controller"><span class="pulse-dot"></span><br>Control<br>digital</div>${Array(5).fill('<div class="valve-module"></div>').join('')}</div><p class="annotation">Representación conceptual de una isla de válvulas.</p><p class="big" style="margin-top:32px">Control y diagnóstico<br><span class="accent">en un mismo conjunto.</span></p></div><div><ol class="steps"><li>Integración digital<small>Estado y diagnóstico del equipo.</small></li><li>Funciones configurables<small>Presión y caudal mediante software, en equipos compatibles.</small></li><li>Supervisión<small>Detección de fugas y seguimiento del comportamiento.</small></li></ol><p class="annotation">La capacidad depende del producto; añade costo y complejidad.</p></div></div>`,{sources:refs(['digital'])}),seconds:40,notes:'La evolución de la neumática incluye una integración más estrecha con el control digital. Las islas de válvulas agrupan funciones y pueden comunicar información de estado al sistema de automatización. También existen terminales que permiten configurar funciones neumáticas mediante software y realizar diagnósticos, por ejemplo de fugas. Esto puede facilitar ajustes y seguimiento del funcionamiento, aunque añade costo y complejidad. Estas capacidades dependen del equipo utilizado; no están presentes en cualquier válvula neumática.'},
 {...block('17 · Caso de estudio','Caso de estudio',c=>`<p class="subtitle">${esc(c.caso.contexto)||'Aplicación industrial seleccionada por el expositor'}</p><div class="case-grid" style="margin-top:35px">${[['necesidad','Necesidad','¿Qué operación o problema debía resolver?'],['solucion','Solución neumática','¿Qué actuador y control utilizó?'],['resultado','Resultado o aprendizaje','Incluye únicamente hallazgos respaldados por la fuente.']].map(([k,t,f])=>`<article><h3>${t}</h3><p class="${c.caso[k]?'':'blank-case'}">${esc(c.caso[k]||f)}</p></article>`).join('')}<article><h3>Fuente del caso</h3><p class="small">${c.caso.fuenteNombre?esc(c.caso.fuenteNombre):'Pendiente de seleccionar'}</p></article></div>${!c.caso.solucion?'<div class="case-status">Espacio reservado. Completa esta diapositiva desde «Personalizar».</div>':''}`,{sources:'Caso por incorporar: no se han inventado una empresa, datos ni resultados.'}),seconds:60,notes:c=>c.caso.solucion?`Este caso corresponde a ${c.caso.contexto||c.caso.titulo}, donde se necesitaba ${c.caso.necesidad}. La solución utilizó ${c.caso.solucion}. Según ${c.caso.fuenteNombre||'la fuente consultada'}, ${c.caso.resultado}. Relaciona aquí la válvula, el actuador y la operación con los conceptos explicados.`:'Reserva un minuto para el caso que buscarás. Explica: empresa o proceso, necesidad, solución neumática y resultado documentado. Si no hay resultados medidos, presenta el aprendizaje sin inventar porcentajes. Completa los campos desde Personalizar y copia la configuración al archivo config.js para llevar el caso a otro equipo.'},
 {...block('18 · Conclusiones','Componentes que trabajan juntos',()=>`<div class="numbered-findings"><div class="finding"><span class="number">01</span><div><h3>Las válvulas gobiernan el aire.</h3><p>Los actuadores convierten su energía en trabajo.</p></div></div><div class="finding"><span class="number">02</span><div><h3>El conjunto determina el desempeño.</h3><p>Selección, conexiones y control deben responder a la misma operación.</p></div></div><div class="finding"><span class="number">03</span><div><h3>El proceso define la conveniencia.</h3><p>Fuerza, velocidad, precisión y costo total orientan la decisión.</p></div></div></div>`,{dark:true}),seconds:25,notes:'Las válvulas establecen cómo circula el aire y los actuadores lo convierten en trabajo mecánico. El desempeño depende de seleccionar y combinar correctamente estos elementos. En la industria, la neumática resulta conveniente cuando sus capacidades responden a la operación y se evalúan tanto los requisitos técnicos como los costos de funcionamiento.'},
 {...block('19 · Referencias','Referencias · 1 de 2',()=>apaList(0,6),{subtitle:'Bibliografía en formato APA 7.'}),seconds:5,notes:'Estas referencias respaldan la exposición. Los enlaces están disponibles aquí para su consulta.'},
 {...block('19 · Referencias','Referencias · 2 de 2',c=>apaList(6,11)+(c.caso.fuenteNombre?'<p class="case-reference"><strong>Fuente del caso:</strong> '+esc(c.caso.fuenteNombre)+(safeUrl(c.caso.fuenteUrl)?' <a href="'+esc(safeUrl(c.caso.fuenteUrl))+'" target="_blank" rel="noopener">'+esc(safeUrl(c.caso.fuenteUrl))+'</a>':'')+'</p>':''),{subtitle:'Bibliografía en formato APA 7.'}),seconds:5,notes:'Estas referencias respaldan la exposición. Los enlaces están disponibles aquí para su consulta.'}
];
function stateDemo(id){return `${svgStart(id,'0 0 500 110')}<rect x="45" y="20" width="350" height="62" rx="5" fill="none" stroke="#8da4a6" stroke-width="2"/><text x="128" y="59" text-anchor="middle">Posición 1</text><text x="304" y="59" text-anchor="middle">Posición 2</text><rect data-state-block="${id}" x="45" y="20" width="175" height="62" rx="5" fill="#006f70" opacity=".19"/><path class="signal" d="M5 50H42"/></svg>`}
function application(kind){return kind==='reject'?`${svgStart('reject','0 0 380 260')}<path class="line" d="M20 160H360M20 190H360"/><circle class="hardware" cx="40" cy="175" r="13"/><circle class="hardware" cx="340" cy="175" r="13"/><rect class="hardware" x="45" y="45" width="110" height="70"/><rect class="metal" x="155" y="71" width="105" height="16"/><rect x="270" y="55" width="45" height="60" fill="#cc7948"/><path d="M320 80h35" class="pipe" marker-end="url(#arrow-reject)"/><text x="190" y="241" text-anchor="middle">Expulsión</text></svg>`:`${svgStart('clamp','0 0 380 260')}<rect class="hardware" x="70" y="50" width="110" height="70"/><rect class="metal" x="180" y="76" width="72" height="16"/><rect class="metal" x="245" y="55" width="12" height="65"/><rect x="262" y="60" width="39" height="58" fill="#cc7948"/><path class="line" d="M315 35V150H40M302 35h25"/><text x="190" y="228" text-anchor="middle">Sujeción</text></svg>`}

/* Revisión local del 9/10/2026. Numeración de origen: las 20 diapositivas de las notas del expositor. */
SLIDES.forEach((s,i)=>{s.originalNumber=Math.min(i+1,20);s.kind='topic-'+(i+1)});
const originalSlide=n=>SLIDES.find(s=>s.originalNumber===n);
const change=(n,patch)=>Object.assign(originalSlide(n),patch);
function annotatedMachine(){return machine('inside',{signal:true}).replace('</svg>','<path d="M594 62L454 129" stroke="#006f70" stroke-width="3" fill="none" marker-end="url(#arrow-inside)"/><text x="596" y="57" class="label-big">Vástago</text></svg>')}
function pistonLabel(){return miniCylinder('force').replace('</svg>','<path d="M232 25L154 94" stroke="#006f70" stroke-width="3" fill="none" marker-end="url(#arrow-force)"/><text x="238" y="30" class="label-big">Émbolo</text></svg>')}
function cylinderDemo(id,single){return `<div class="cylinder-demo" data-cylinder="${id}">${svgStart(id,'0 0 540 250')}<rect class="hardware" x="45" y="65" width="290" height="104" rx="5"/><rect data-demo-left x="49" y="69" width="58" height="96" fill="#087cb533"/><rect data-demo-right x="123" y="69" width="208" height="96" fill="#c0592f22"/><g data-demo-piston><rect class="metal" x="107" y="68" width="16" height="98"/><rect class="metal" x="123" y="111" width="255" height="17"/></g>${single?'<path data-demo-spring class="line" d="M125 149L145 137L165 161L185 137L205 161L225 137L245 161L265 137L285 161L305 137L328 149"/><text x="255" y="45" text-anchor="middle">Resorte</text>':''}<path data-demo-in class="pipe" d="M65 207V169"/>${single?'':'<path data-demo-out class="pipe exhaust" d="M314 169V207"/>'}<text data-demo-state x="270" y="240" text-anchor="middle">${single?'Sin alimentación: resorte extendido':'Aire hacia la cámara del vástago'}</text></svg><div class="scene-controls"><button data-cylinder-id="${id}" data-cylinder-target="1">${single?'Dar aire':'Avance'}</button><button data-cylinder-id="${id}" data-cylinder-target="0" class="selected">${single?'Descargar / retorno':'Retorno'}</button></div></div>`}
function operationDiagram(){return `${svgStart('requirements','0 0 620 230')}<rect class="hardware" x="25" y="75" width="190" height="75"/><rect class="metal" x="215" y="103" width="130" height="18"/><rect x="345" y="89" width="58" height="62" fill="#cc7948"/><path class="line" d="M320 154H595"/><path d="M403 112H515" stroke="#087cb5" stroke-width="6" marker-end="url(#arrow-requirements)"/><text x="455" y="91" text-anchor="middle">Fuerza F</text><path d="M345 55H540" stroke="#006f70" stroke-width="3" marker-end="url(#arrow-requirements)"/><text x="430" y="31" text-anchor="middle">Velocidad v</text><path d="M345 175V210M550 175V210M345 194H550" stroke="#536870" stroke-width="2" fill="none" marker-end="url(#arrow-requirements)"/><text x="446" y="226" text-anchor="middle">Carrera: distancia recorrida</text></svg>`}
function industrialIcon(kind){let drawing='';
 if(kind==='fill')drawing='<path class="line" d="M45 195V50H290V85M145 55V115M245 55V115"/><path class="pipe" d="M25 85H70V125H110"/><path class="hardware" d="M119 129H171V205H119ZM219 129H271V205H219Z"/><path d="M126 179H164M226 179H264" stroke="#087cb5" stroke-width="30"/><path class="line" d="M90 211H295"/>';
 if(kind==='seal')drawing='<path class="hardware" d="M60 40H300V210H280V85H80V210H60Z"/><rect class="metal" x="155" y="82" width="28" height="40"/><rect class="hardware" x="93" y="118" width="175" height="22"/><rect class="hardware" x="93" y="162" width="175" height="22"/><path d="M130 142L225 142L239 215H118Z" fill="#cc794866" stroke="#c0592f" stroke-width="2"/><path class="pipe" d="M30 35H168V80"/>';
 if(kind==='rivet')drawing='<rect class="hardware" x="40" y="55" width="220" height="90" rx="10"/><rect class="metal" x="260" y="84" width="35" height="24"/><path class="hardware" d="M85 145H135V208H85Z"/><path class="pipe" d="M109 208V233H35"/><path d="M308 40V190M322 40V190" stroke="#708b96" stroke-width="9"/><path d="M289 96H339" stroke="#c0592f" stroke-width="10"/>';
 return svgStart('industry-'+kind,'0 0 380 260')+drawing+'</svg>';
}
change(1,{body:c=>`<div class="cover"><div><p class="eyebrow">Manufactura automatizada</p><h1>Sistemas<br>neumáticos</h1><p class="lead">Válvulas, cilindros y actuadores.</p><div class="meta"><strong>${esc(c.nombre)}</strong><br>${esc(c.curso)}<br>Profesor: ${esc(c.profesor)}<br>${esc(c.fecha)}</div><p class="ai-credit">Diagramas y animaciones hechos con IA.</p></div><div class="svgwrap">${machine('cover')}</div></div>`});
change(2,{body:()=>`<div class="scope-flow">${[['01','Generación'],['02','Almacenamiento<br>y tratamiento'],['03','Distribución'],['04','Consumo<br>en la máquina']].map(([n,t],i)=>`${i?'<span class="arrow" aria-hidden="true">›</span>':''}<div class="station ${i<3?'dim':''}"><span>${n}</span><h3>${t}</h3></div>`).join('')}</div><div class="scope-zoom"><p class="big">Cómo la máquina controla<br><span class="accent">y aprovecha el aire comprimido</span></p><button class="zoom-button" data-next>Entrar a la máquina ↗</button></div>`});
change(3,{title:'El sistema neumático dentro de la máquina',subtitle:'Controlar el aire. Realizar trabajo.',body:()=>`<div class="split wide"><div><div class="svgwrap">${annotatedMachine()}</div><div class="legend"><span><i></i>Alimentación</span><span><i class="out"></i>Descarga</span><span><i class="sig"></i>Mando</span></div></div><div><ol class="steps"><li>Válvula<small>Decide por dónde circula el aire.</small></li><li>Cilindro<small>Su vástago transmite el movimiento.</small></li><li>Proceso<small>Recibe la fuerza y el movimiento.</small></li></ol></div></div>`});
change(5,{body:()=>`<div class="compare"><div><p class="mini-label">Presión y área</p><p class="formula">F<sub>teórica</sub> = p A</p><p>Fuerza de empuje del vástago sobre la pieza.</p><div class="svgwrap">${pistonLabel()}</div></div><div><p class="mini-label">Caudal y área</p><p class="formula">v ≈ Q / A</p><p>Velocidad de desplazamiento del vástago.</p><p class="flow-definition"><strong>Caudal:</strong> volumen de aire que pasa por unidad de tiempo.</p><div class="relation-box"><p><strong>A igual área:</strong><br>más caudal → vástago más rápido.</p><p><strong>A igual caudal:</strong><br>más área → vástago más lento.</p></div></div></div><p class="annotation">Relaciones simplificadas: p: presión sobre el émbolo; A: área efectiva de su cara; Q: caudal en la cámara. Modelo ideal de avance con escape atmosférico.</p><p class="takeaway force-summary">Elegimos la presión y el tamaño del cilindro para conseguir el empuje que necesita la operación. Ajustamos el caudal para que el vástago haga el recorrido a la velocidad requerida.</p>`});
