change(11,{body:()=>`<div class="calc-grid"><div><div class="svgwrap requirements">${operationDiagram()}</div><div class="calc-controls"><label for="pressure">Presión: <b id="pValue">6</b> bar<input type="range" id="pressure" min="2" max="8" step="0.5" value="6"></label><label for="diameter">Diámetro: <b id="dValue">20</b> mm<input type="range" id="diameter" min="10" max="50" step="2" value="20"></label></div><div class="scene-controls"><button data-reset-calc>Volver al ejemplo</button></div></div><div><p class="mini-label">Fuerza teórica de avance</p><p class="result"><span id="forceValue">188</span> <small>N</small></p><div class="rule"></div><p class="copy">F = p · πD² / 4</p><p class="small" id="calcDetail"></p></div></div><p class="calculation-assumptions">Escape atmosférico, sin fricción. No incluye contrapresión, cargas dinámicas ni margen de selección.</p>`});
change(13,{kind:'cycle',body:()=>`<div class="split wide"><div><div class="svgwrap">${machine('speed',{regulator:true})}</div><div class="scene-controls"><button data-speed="0.45">Lento</button><button data-speed="1" class="selected">Normal</button><button data-speed="1.8">Rápido</button><button data-auto-cycle>Reproducir ciclo</button></div></div><div class="copy"><h3>Regulador unidireccional</h3><p>Limita el paso en un sentido y permite paso libre en el contrario.</p></div></div>`});
